			title = "Importancia",
			text = [=[Vestia fue la primera en decir en voz alta lo que la reliquia podía significar. No pertenecía a las ruinas de donde procedía, y no era de factura {link:naga}naga{/link}. Era algo más extraño que ambas cosas.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Sirve a {link:feathermoon-stronghold}Plumaluna{/link} como su sacerdotisa.
• Ha tomado la reliquia {link:naga}naga{/link} para estudiarla, y aún no sabe qué es.]=],
		},
	},
	mentions = {
		{ text = "La entrega de la reliquia" },
	},
	bonds = {
		{ id = "latronicus-moonspear", name = "Latronicus Moonspear", note = "su esposo" },
		{ id = "lord-shalzaru", name = "Señor Shalzaru", note = "halló la reliquia que ella estudia" },
	},
})

Translate("esMX", "ginro-hearthkindle", {
	title = "Ginro Hearthkindle",
	subtitle = "Buscador de Plumaluna",
	found = "Bastión Plumaluna, en sus aposentos",
	hint = [=[Encuentre al centinela que no deja de buscar a un correo perdido.]=],
	allegiance = "Centinelas · Bastión Plumaluna",
	aliases = { "Ginro", "Gin" },
	sections = {
		{
			title = "Resumen",
			text = [=[Ginro Hearthkindle es un soldado del {link:feathermoon-stronghold}Bastión Plumaluna{/link} que no quiso abandonar a un amigo. Cuando el correo {link:raschal-the-courier}Raschal{/link} desapareció en el camino a {link:thalanaar}Thalanaar{/link}, Ginro salía cada día a las tierras salvajes a buscarlo, y volvía cada noche sin nada más que dientes de {link:gnolls}gnoll{/link}. Incluso después de que el bastión diera a Raschal por perdido, siguió buscando.]=],
		},
		{
			title = "Importancia",
			text = [=[La búsqueda de Ginro sacó a la luz el peligro más grave de {link:feralas}Feralas{/link}. Siguiendo a un correo perdido, los buscadores encontraron la colmena Zukk'ash, la primera señal en estas tierras de los silítidos del sur.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Buscó a {link:raschal-the-courier}Raschal{/link} día tras día, solo.
• Envió el cuchillo del correo al druida {link:quintis-jonespyre}Quintis Jonespyre{/link} para que lo leyera por el tacto, y le pagó perdonándole una deuda de cartas.
• Instó a un ataque directo contra los campamentos Zarpaleña cuando la visión del druida señaló hacia allí.
• Presentó a los rescatadores de Raschal ante {link:shandris-feathermoon}Shandris Feathermoon{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Los restos del naufragio",
			hint = "Busque la barca del correo en la costa de Feralas.",
			text = [=[{link:raschal-the-courier}Raschal{/link} había querido remar costa abajo y cruzar el sur de {link:feralas}Feralas{/link}, para mantenerse lejos del campamento de la {link:horde}Horda{/link}. Su barca apareció hundida y destrozada, con el emblema del bastión todavía en el costado. En el fango, bajo ella, estaba su cuchillo. Algo en el agua había estado a punto de partir la barca en dos.]=],
		},
		{
			title = "El cuchillo revela",
			hint = "Averigüe lo que recuerda el cuchillo del correo.",
			text = [=[{link:quintis-jonespyre}Quintis{/link} sostuvo el cuchillo y vio a {link:raschal-the-courier}Raschal{/link} llevar dos fardos tierra adentro, encontrarse con los Zarpaleña y volver a su barca asustado. Raschal no temía nada de lo que pudieran hacer los gnolls. Otra cosa lo había asustado, tanto que nunca vio el agua alzarse detrás de él. Ginro supo entonces que no estaba buscando un cadáver.]=],
		},
		{
			title = "Liberado de la colmena",
			hint = "Siga el rastro del correo hasta el final.",
			text = [=[Los fardos colgaban de un árbol en los campamentos Zarpaleña. Dentro había una nota: {link:raschal-the-courier}Raschal{/link} había encontrado insectos al sur de los gnolls y había ido a verlos él mismo. En {link:the-writhing-deep}Las Galerías Retorcidas{/link} lo encontraron sellado en una vaina, aturdido pero vivo. Ginro dijo a sus rescatadores que siempre tendrían en él a un amigo.]=],
		},
	},
	mentions = {
		{ text = "El correo desaparecido" },
		{ text = "Los restos de la barca" },
		{ text = "El cuchillo revela" },
		{ text = "Lectura psicométrica" },
		{ text = "Los gnolls Zarpaleña" },
		{ text = "{link:the-writhing-deep}Las Galerías Retorcidas{/link}" },
		{ text = "Liberado de la colmena" },
		{ text = "La bienvenida de un héroe" },
	},
	bonds = {
		{ id = "raschal-the-courier", name = "Raschal el Correo", note = "el amigo al que buscó" },
		{ id = "quintis-jonespyre", name = "Quintis Jonespyre", note = "leyó el cuchillo, y le debía en las cartas" },
		{ id = "latronicus-moonspear", name = "Latronicus Moonspear", note = "le envió ayuda" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "su general" },
	},
})

