Translate("esMX", "troyas-moonbreeze", {
	title = "Troyas Moonbreeze",
	subtitle = "Buscador de ruinas",
	found = "Bastión Plumaluna, con su esposa y sus mascotas",
	hint = [=[Hable con el erudito de Plumaluna que explora las viejas ruinas.]=],
	allegiance = "Bastión Plumaluna",
	aliases = { "Troyas" },
	sections = {
		{
			title = "Resumen",
			text = [=[Troyas Moonbreeze y su esposa {link:angelas-moonbreeze}Angelas{/link} estudian las ruinas dispersas por {link:feralas}Feralas{/link}. Él cree que las piedras aún tienen mucho que contar. Su colega de {link:darnassus}Darnassus{/link} opina que ve tesoros en cada montón de escombros. Últimamente ha estado yendo solo a las {link:high-wilderness}Altas Tierras Salvajes{/link}, lo que asusta a su esposa.]=],
		},
		{
			title = "Importancia",
			text = [=[Troyas tuvo razón al menos una vez. Una vara que encontró en las ruinas del sur resultó ser la llave del Monolito de Equinex, y este se abrió.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Encontró una vara de aspecto corriente en las ruinas y no quiso deshacerse de ella.
• Pidió el libro {i}{link:feralas}Feralas{/link}: A History{/i} a la custodia del saber Daryn Lightwind.
• Ha empezado a estudiar la Morrow Stone, sacada del monolito.]=],
		},
	},
	chapters = {
		{
			title = "La Morrow Stone",
			hint = [=[Lleve la vara del erudito al monolito de las ruinas del norte.]=],
			text = [=[Cargada con la esencia de cuatro viejas llamas, la vara se volvió demasiado pesada de poder para sostenerla. A su contacto, el Monolito de Equinex abrió una pequeña puerta, y dentro había una piedra centelleante. Troyas leyó que se llamaba Morrow Stone. No conoce su propósito. Solo sabe que nadie esconde con tanto cuidado una piedra corriente.]=],
