Translate("esMX", "angelas-moonbreeze", {
	title = "Angelas Moonbreeze",
	subtitle = "Buscadora de ruinas",
	found = "Bastión Plumaluna, junto a su esposo",
	hint = "Hable con la erudita que teme por la seguridad de su esposo.",
	allegiance = "Bastión Plumaluna",
	aliases = { "Angelas" },
	sections = {
		{
			title = "Resumen",
			text = [=[Angelas Moonbreeze comparte el amor de su esposo {link:troyas-moonbreeze}Troyas{/link} por las viejas ruinas, y buena parte de su saber. No comparte su imprudencia. Cuando él empezó a adentrarse solo en las {link:high-wilderness}Altas Tierras Salvajes{/link}, donde mandan los ogros Gordunni, ella pidió discretamente a otros que le despejaran el camino, y que no le dijeran nada.]=],
		},
		{
