	allegiance = "Ninguna",
	sections = {
		{
			title = "Resumen",
			text = [=[Rockbiter es un gigante de las colinas del norte de {link:feralas}Feralas{/link}, y uno apacible. Debía velar por {link:shay-leafrunner}Shay Leafrunner{/link}, una joven elfa de la noche que se extravía. En un momento estaba a su lado en las ruinas al norte de su campamento. Al siguiente, había desaparecido, y él no sabía qué hacer.]=],
		},
		{
			title = "Importancia",
			text = [=[En un bosque donde la mayoría de los gigantes son peligrosos, Rockbiter recuerda que no todos lo son. Su amistad con una pequeña niña elfa es una de las historias más amables de {link:feralas}Feralas{/link}.]=],
		},
