			title = "Hazañas",
			text = [=[• Pidió a un viajero que encontrara a Shay, ya que unas piernas pequeñas son más rápidas que las suyas.
• Guarda ahora la campanilla de ella, para poder llamarla de vuelta.]=],
		},
	},
	mentions = {
		{ text = "El gigante guardián" },
		{ text = "Shay la errante" },
	},
	bonds = {
		{ id = "shay-leafrunner", name = "Shay Leafrunner", note = "la niña a la que protege" },
	},
})

