Translate("esMX", "hadoken-swiftstrider", {
	title = "Hadoken Swiftstrider",
	subtitle = "Guerrero del Campamento Mojache",
	found = "Campamento Mojache",
	hint = [=[Hable con el líder guerrero que defiende el Campamento Mojache de los gnolls.]=],
	allegiance = "Horda · Campamento Mojache",
	aliases = { "Hadoken" },
	sections = {
		{
			title = "Resumen",
			text = [=[Hadoken Swiftstrider dirige la defensa del {link:camp-mojache}Campamento Mojache{/link}. No tiene paciencia para la cuestión de si los gnolls Zarpaleña pertenecen a {link:feralas}Feralas{/link}. Atacan su campamento, y si la {link:horde}Horda{/link} no se mantiene firme, será expulsada de la región. Es un veterano que ha leído muchos planes de batalla, y reconoce a un enemigo desesperado cuando lo ve.]=],
		},
		{
			title = "Importancia",
			text = [=[Hadoken fue el primero de la {link:horde}Horda{/link} en ver que los gnolls no eran la verdadera amenaza. Siguió su miedo hacia el sur y encontró a los Zukk'ash, y su informe sobre ellos llegó a {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Ordenó abatir a los alfas Zarpaleña uno tras otro, rápidamente, para sumir a los gnolls en el caos.
• Envió a buscar los planes de batalla de los gnolls.
• Ordenó diezmar a los Zukk'ash de {link:the-writhing-deep}Las Galerías Retorcidas{/link}, y abrir a su mayor bestia, {link:stinglasher}Stinglasher{/link}, para estudiarla.
• Envió el informe del campamento sobre los insectos a Zilzibin Drumlore, en {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Guerra contra los Zarpaleña",
			hint = [=[Haga retroceder a los gnolls que asaltan el Campamento Mojache.]=],
			text = [=[Los Zarpaleña siempre habían asaltado el campamento, y la {link:horde}Horda{/link} siempre los había contenido. Últimamente los asaltos se habían vuelto salvajes y constantes, como si los gnolls no tuvieran otro lugar adonde ir. Hadoken quiso quebrarlos con un solo golpe certero. Funcionó, por un tiempo. También le hizo preguntarse qué los había llevado a semejante frenesí.]=],
		},
		{
			title = "Los planes de batalla",
			hint = [=[Encuentre los planes de batalla de los gnolls en sus campamentos del sur.]=],
			text = [=[El mapa de los gnolls contaba la historia. La mayoría de sus flechas apuntaban al sur, lejos del {link:camp-mojache}Campamento Mojache{/link}, y junto al dibujo de un gran insecto había hileras de marcas de recuento: sus muertos. Los Zarpaleña libraban una guerra en dos frentes, y la que estaban perdiendo no era contra la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Los Zukk'ash",
			hint = [=[Lleve a Orgrimmar el informe del campamento sobre los insectos.]=],
			text = [=[A Hadoken no le importaba si los insectos podían pensar. Empujaban a los gnolls contra su campamento, y por tanto eran su enemigo. Cuando sus hallazgos llegaron a Zilzibin Drumlore, en {link:orgrimmar}Orgrimmar{/link}, el goblin dio a los insectos su verdadero nombre, silítidos, y advirtió que la {link:horde}Horda{/link} los había ignorado demasiado tiempo.]=],
		},
	},
	mentions = {
		{ text = "Guerra contra los Zarpaleña" },
		{ text = "Ataque alfa" },
		{ text = "Investigación de los Zarpaleña" },
		{ text = "Los planes de batalla" },
		{ text = "Infestación Zukk'ash" },
		{ text = "{link:stinglasher}Stinglasher{/link}" },
		{ text = "Informe sobre los Zukk'ash" },
	},
	bonds = {
		{ id = "stinglasher", name = "Stinglasher", note = "la bestia que quería estudiar" },
		{ id = "rok-orhan", name = "Rok Orhan", note = "combate a los ogros a su lado" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "ocupa el bastión de la Alianza en el oeste" },
	},
})

