Translate("esMX", "witch-doctor-uzer-i", {
	title = "Médico brujo Uzer'i",
	subtitle = "Médico brujo del Campamento Mojache",
	found = "Campamento Mojache",
	hint = [=[Hable con el médico brujo trol del Campamento Mojache que busca una vasija especial.]=],
	allegiance = "Horda · Campamento Mojache",
	aliases = { "Uzer'i" },
	sections = {
		{
			title = "Resumen",
			text = [=[El médico brujo Uzer'i es un trol del {link:camp-mojache}Campamento Mojache{/link} y maestro de un arte antiguo e inquietante. Conoce el muisek, el espíritu que una criatura deja tras de sí cuando muere por la violencia. Según enseña, ese espíritu puede escapar, buscar venganza e incluso regresar con la forma de una bestia mayor. Uzer'i ha hallado el modo de impedirlo. Una criatura encogida y capturada en el instante de su muerte no puede soltar su muisek, y un muisek capturado puede usarse.]=],
		},
		{
			title = "Importancia",
			text = [=[La obra de Uzer'i es un arma dirigida contra los elfos de la noche. Elige sus criaturas por su vínculo con los {link:night-elves}kaldorei{/link}: las lechubestias, antaño mascotas de Elune; los hipogrifos, sus leales monturas; los dragones feéricos, sus aliados; los antárboles, sus protectores; y los gigantes de montaña, que bajaron de sus cumbres para ayudarlos contra la {link:burning-legion}Legión Ardiente{/link}. Su fuerza, dice, también debería servir a la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Cambió la cabeza reducida de un {link:dwarves}enano{/link} a {link:neeru-fireblade}Neeru Fireblade{/link}, de {link:orgrimmar}Orgrimmar{/link}, por las hierbas que necesitaba su vasija.
• Envió cazadores hasta las {link:the-hinterlands}Tierras del Interior{/link} para capturar el muisek de las lechubestias.
• Selló los espíritus capturados en armas.]=],
		},
	},
	chapters = {
		{
			title = "La vasija muisek",
			hint = "Traiga al médico brujo las hierbas que espera de Orgrimmar.",
			text = [=[{link:neeru-fireblade}Neeru Fireblade{/link} había preparado las hierbas, y quedó satisfecho con la cabeza que recibió a cambio. Uzer'i realizó enseguida su ritual sobre la vasija. Su primera prueba estaba lejos, entre las lechubestias de {link:the-hinterlands}las Tierras del Interior{/link}, y pondría a prueba tanto el ritual como al cazador que llevara la vasija.]=],
		},
		{
			title = "Armas del espíritu",
			hint = "Complete la colección de espíritus del médico brujo.",
			text = [=[Hipogrifo, dragón feérico, antárbol y gigante de montaña: uno a uno, los aliados de los elfos de la noche fueron encogidos y atrapados. Con madera astillada, minerales, tendones y fragmentos de metal, Uzer'i ató sus espíritus para siempre a las armas que forjó.]=],
		},
	},
	mentions = {
		{ text = "Una petición extraña" },
		{ text = "Regreso con el médico brujo Uzer'i" },
		{ text = "Prueba de la vasija" },
		{ text = "Muisek de hipogrifo" },
		{ text = "Muisek de dragón feérico" },
		{ text = "Muisek de antárbol" },
		{ text = "Muisek de gigante de montaña" },
		{ text = "Materiales naturales" },
		{ text = "Armas del espíritu" },
	},
	bonds = {
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "le cambia hierbas" },
	},
})

