	allegiance = "Horda · Campamento Mojache",
	aliases = { "Korolusk" },
	sections = {
		{
			title = "Resumen",
			text = [=[El sabio Korolusk ha seguido un largo rastro hasta {link:feralas}Feralas{/link}. Busca a Kariel Winthalus, un maestro élfico que huyó de la devastación de su tierra natal con antiguos artefactos élficos. El rastro partió de las ruinas de {link:quel-thalas}Quel'Thalas{/link}, atravesó {link:burning-steppes}Las Estepas Ardientes{/link} y cruzó el mar, y termina, cree Korolusk, en las salas de Eldre'Thalas.]=],
		},
		{
			title = "Importancia",
			text = [=[Korolusk y el erudito {link:scholar-runethorn}Runethorn{/link} de {link:feathermoon-stronghold}Plumaluna{/link} persiguen al mismo hombre en busca del mismo saber, uno para la {link:horde}Horda{/link} y otro para la {link:alliance}Alianza{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Pide que se registre La Marra en busca de Kariel, vivo o muerto.]=],
		},
	},
	mentions = {
		{ text = "Leyendas élficas" },
	},
	bonds = {
		{ id = "scholar-runethorn", name = "Erudito Runethorn", note = "busca al mismo maestro" },
	},
})

