Translate("esMX", "falfindel-waywarder", {
	title = "Falfindel Waywarder",
	subtitle = "Druida de Thalanaar",
	found = "Thalanaar, en el límite oriental de Feralas",
	hint = [=[Busque al druida que guarda la posta en el límite oriental del bosque.]=],
	allegiance = "Círculo Cenarion · Thalanaar",
	aliases = { "Falfindel" },
	sections = {
		{
			title = "Resumen",
			text = [=[Falfindel Waywarder es un druida de los elfos de la noche que guarda {link:thalanaar}Thalanaar{/link}, la solitaria posta donde los bosques de {link:feralas}Feralas{/link} se encuentran con los cañones de {link:thousand-needles}Las Mil Agujas{/link}. Los guardianes de la {link:stonetalon-mountains}Sierra Espolón{/link} lo llaman grande y sabio. Se dice que puede llamar a los grandes espíritus del bosque para que acudan en ayuda de las tierras heridas.]=],
		},
		{
			title = "Importancia",
			text = [=[Desde su tranquilo puesto, Falfindel vela por algo más que {link:feralas}Feralas{/link}. Su preocupación llega hasta {link:the-barrens}Los Baldíos{/link}, donde el lugar de reposo del semidiós jabalí Agamaggan ha sido corrompido, y tan al norte como la {link:stonetalon-mountains}Sierra Espolón{/link}, cuyo guardián le ha suplicado ayuda.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudia qué corrompió el lugar de reposo de Agamaggan en el sur de {link:the-barrens}Los Baldíos{/link}.
• Envió a otros contra la vieja {link:charlga-razorflank}Charlga Razorflank{/link} del {link:razorfen-kraul}Horado Rajacieno{/link}.
• Responde a la súplica del {link:keeper-albagorm}guardián Albagorm{/link} de enviar espíritus del bosque al Charred Vale.
• Espera los suministros que los correos llevan a través de {link:feralas}Feralas{/link} desde {link:feathermoon-stronghold}Plumaluna{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La vieja del Horado",
			hint = "Lleve a Thalanaar el diario de un enano muerto.",
			text = [=[El diario de Henrig Lonebrow habló a Falfindel del druida {link:heralath-fallowbrook}Heralath{/link}, capturado en {link:razorfen-kraul}el Horado{/link}, y de una vieja que se hacía más fuerte cada día. No había tiempo de pedir ayuda a {link:darnassus}Darnassus{/link}. Cuando el medallón de la vieja volvió a sus manos, se atrevió a esperar que sus estudios pudieran continuar, aunque temía que la respuesta a ellos fuera una traición.]=],
		},
		{
			title = "Una llamada desde la Sierra Espolón",
			hint = [=[Lleve la súplica del guardián Albagorm al druida de Thalanaar.]=],
			text = [=[Las arpías del Charred Vale habían sido quebrantadas, pero volverían, y las semillas solas no podrían sanar el valle antes de que lo hicieran. {link:keeper-albagorm}Albagorm{/link} envió aviso a Falfindel a través de medio {link:kalimdor}Kalimdor{/link}. El druida no malgastó palabras. Se puso de inmediato a llamar en su ayuda al gran bosque.]=],
		},
		{
			title = "El paquete tardío",
			hint = "Lleve a Thalanaar el paquete perdido del correo.",
			text = [=[El paquete de {link:feathermoon-stronghold}Plumaluna{/link} llegó tarde y de manos de un extraño. Falfindel supuso al instante que algo le había ocurrido a {link:raschal-the-courier}Raschal{/link}, el correo habitual. Tenía sus propias sospechas: los Zarpaleña se habían vuelto inquietos últimamente, agitados por algo del sur.]=],
		},
	},
	mentions = {
		{ text = "Diario de Soliceja" },
		{ text = "La vieja del {link:razorfen-kraul}Horado{/link}" },
		{
			text = [=[Recuperar el Charred Vale, la súplica desde la {link:stonetalon-mountains}Sierra Espolón{/link}]=],
		},
		{ text = "Entrega en {link:thalanaar}Thalanaar{/link}" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "Guardián Albagorm", note = "le pidió ayuda" },
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "el druida capturado en el Horado" },
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "enemiga" },
		{ id = "raschal-the-courier", name = "Raschal el Correo", note = "su correo habitual" },
	},
})

